    // -------------- ESTRUCTURA PARA PARAMETROS----------
    public static class Parametro {
        public final String nombre;
        public final String tipo;      // "INT", "REAL", "STRING", "CHAR"
        public final int posicion;     // 0, 1, 2, ...

        public Parametro(String nombre, String tipo, int posicion) {
            this.nombre = nombre;
            this.tipo = tipo;
            this.posicion = posicion;
        }
    }

    //  ESTRUCTURA PARA LOS ITEMS DE LA TABLA DE SIMBOLOS----------
    public static class EntradaTS {

      public enum Clase {
          VARIABLE,
          FUNCION,
          PROCEDIMIENTO
      }

      public final String nombre;
      public final Clase clase;

      /**
       * VARIABLE: tipo de la variable
       * FUNCION : tipo de retorno
       * PROC    : normalmente "VOID" o null
       */
      public final String tipo;

      /** Solo tiene sentido si clase == VARIABLE. */
      public final boolean esLocal;
      public final String bloque;
      public final boolean esParametro;


      /** Solo se usa si clase == FUNCION o PROCEDIMIENTO. */
      public final java.util.List<Parametro> parametros;

      public EntradaTS(String nombre,
                        Clase clase,
                        String tipo,
                        boolean esLocal,
                        String bloque,
                        boolean esParametro,
                        java.util.List<Parametro> parametros) {
            this.nombre = nombre;
            this.clase = clase;
            this.tipo  = tipo;
            this.esLocal = esLocal;
            this.bloque = bloque;
            this.esParametro = esParametro;

            if (parametros == null) {
                this.parametros = java.util.Collections.emptyList();
            } else {
                this.parametros = new java.util.ArrayList<>(parametros);
            }
        }

        public int cantidadParametros() {
            return parametros.size();
        }
    }

    public void checkRoutineCall(Object idTok, Object argsObj, int line, boolean usedAsExpr) {
        if (idTok == null) return;

        String nombre = idTok.toString();

        // Buscar en la TS
        EntradaTS ent = buscarTS(nombre);
        if (ent == null) {
            addSemanticError("Función o procedimiento '" + nombre + "' no definido", line);
            return;
        }

        if (ent.clase != EntradaTS.Clase.FUNCION &&
            ent.clase != EntradaTS.Clase.PROCEDIMIENTO) {
            addSemanticError(
                "Identificador '" + nombre + "' no es función ni procedimiento",
                line
            );
            return;
        }

        // Lista de argumentos recibidos (List<DO>)
        java.util.List args =
            (argsObj instanceof java.util.List)
                ? (java.util.List) argsObj
                : new java.util.ArrayList();

        int dados    = args.size();
        int esperados = (ent.parametros == null) ? 0 : ent.parametros.size();

        // Cantidad de parámetros
        if (dados != esperados) {
            addSemanticError(
                "Cantidad de parámetros incorrecta al llamar '" + nombre +
                "': se esperaban " + esperados + " y se recibieron " + dados,
                line
            );
            return; // ya con eso basta
        }

        // Tipo de cada parámetro
        for (int i = 0; i < esperados; i++) {
            Parametro p = ent.parametros.get(i);
            DO d        = (DO) args.get(i);

            String tipoFormal   = p.tipo;
            String tipoActual   = d.tipo;

            if (!tipoFormal.equals(tipoActual)) {
                addSemanticError(
                    "Tipo de parámetro " + (i + 1) + " incorrecto en llamada a '" + nombre +
                    "': se esperaba " + tipoFormal + " y se recibió " + tipoActual,
                    line
                );
            }
        }

        // Si quisieras, aquí podrías validar:
        // - si se usa en expresión, debería ser FUNCION, etc.
    }

    public String bloqueActual = "GLOBAL";
